UPDATE meeting_minutes
SET ai_status = 10, ai_error = #{error}, ai_attempts = #{attempts},
    ai_started_at = NULL, ai_finished_at = #{finishedAt}
WHERE id = #{id} AND ai_status = 20

    AND ai_started_at = #{startedAt}
    AND ai_started_at IS NULL

UPDATE meeting_minutes
SET ai_status = 40, ai_error = #{error}, ai_attempts = #{attempts},
    ai_finished_at = #{finishedAt}
WHERE id = #{id} AND ai_status = 20

    AND ai_started_at = #{startedAt}
    AND ai_started_at IS NULL

UPDATE meeting_minutes
SET asr_error = #{error}, asr_attempts = #{attempts}, asr_finished_at = #{finishedAt}
WHERE id = #{id} AND asr_status = 10

    AND asr_started_at = #{startedAt}
    AND asr_started_at IS NULL

UPDATE meeting_minutes
SET asr_status = 40, asr_error = #{error}, asr_attempts = #{attempts},
    asr_finished_at = #{finishedAt}
WHERE id = #{id} AND asr_status = 10

    AND asr_started_at = #{startedAt}
    AND asr_started_at IS NULL
